<template><section class="settings-section"><b-alert :show="!!error" variant="danger">{{ error }}</b-alert><div v-if="!form" role="status">Загрузка настроек фермы…</div><template v-else>
<section class="settings-card"><div class="settings-card-title"><h6>Сдача флагов</h6><b-form-checkbox v-model="form.enabled" switch>Отправка включена</b-form-checkbox></div><div class="row">
<b-form-group class="col-md-4" label="Протокол" label-for="farm-protocol"><b-form-select id="farm-protocol" v-model="form.protocol" :options="[{value:'ructf_http',text:'RuCTF HTTP (по умолчанию)'},{value:'forcad',text:'ForcAD HTTP'},{value:'volga',text:'Volga API v1'}]"/></b-form-group>
<b-form-group class="col-md-8" label="Адрес борды / URL сдачи" label-for="farm-url" :description="form.protocol==='volga'?'Базовый URL API, например https://board/api/flag/v1':'Полный URL приёма флагов, например http://10.10.10.10:8080/flags'"><b-form-input id="farm-url" v-model.trim="form.url" placeholder="http://10.10.10.10:8080/flags"/></b-form-group>
<b-form-group class="col-md-6" label="X-Team-Token" label-for="farm-token" :description="form.tokenSet?'Токен сохранён. Оставьте поле пустым, чтобы сохранить его.':'Токен команды для RuCTF / ForcAD'"><b-form-input id="farm-token" type="password" autocomplete="new-password" v-model="form.token"/><b-form-checkbox v-if="form.tokenSet" v-model="form.clearToken">Удалить сохранённый токен</b-form-checkbox></b-form-group>
<b-form-group class="col-md-6" label="Формат флага (regex)" label-for="farm-regex"><b-form-input id="farm-regex" v-model="form.flagFormat"/></b-form-group></div></section>
<section class="settings-card"><h6>Цели и исключения</h6><div class="row"><b-form-group class="col-md-6" label="Шаблон IP" label-for="farm-pattern" description="{n} заменяется номером команды; пусто — только ручные цели"><b-form-input id="farm-pattern" v-model.trim="form.pattern" placeholder="10.60.{n}.3"/></b-form-group><b-form-group class="col-md-3" label="Первая команда" label-for="farm-first"><b-form-input id="farm-first" type="number" v-model.number="form.first"/></b-form-group><b-form-group class="col-md-3" label="Последняя команда" label-for="farm-last"><b-form-input id="farm-last" type="number" v-model.number="form.last"/></b-form-group>
<b-form-group class="col-md-6" label="Дополнительные цели: имя = IP, по одной в строке" label-for="farm-targets"><b-form-textarea id="farm-targets" v-model="targets" rows="4" placeholder="Team extra = 10.60.70.3"/></b-form-group><b-form-group class="col-md-6" label="Исключить IP (включая свою команду)" label-for="farm-exclude"><b-form-textarea id="farm-exclude" v-model="exclude" rows="4" placeholder="10.60.1.3"/></b-form-group></div><b-button size="sm" variant="outline-secondary" @click="preview">Проверить список целей</b-button><div v-if="previewTargets" class="mt-2 small">{{ previewTargets.length }} целей: {{ previewTargets.map(t=>t.name+' · '+t.host).join(', ') }}</div></section>
<section class="settings-card"><h6>Очередь и клиент</h6><div class="row"><b-form-group v-for="f in numbers" :key="f.key" class="col-md-4" :label="f.label" :label-for="'farm-'+f.key"><b-form-input :id="'farm-'+f.key" type="number" :min="f.min" :max="f.max" v-model.number="form[f.key]"/></b-form-group></div></section>
<div class="settings-footer"><span role="status">{{ saved?'Настройки фермы сохранены':'' }}</span><b-button variant="primary" :disabled="saving" @click="save">{{ saving?'Сохранение…':'Сохранить ферму' }}</b-button></div></template></section></template>
<script>
export default {
 data:()=>({form:null,targets:'',exclude:'',previewTargets:null,error:'',saved:false,saving:false,numbers:[{key:'period',label:'Период сдачи, с',min:1,max:300},{key:'batch',label:'Флагов за период',min:1,max:100},{key:'lifetime',label:'Срок жизни флага, с',min:10,max:86400},{key:'retention',label:'Хранение истории, с',min:10,max:2592000},{key:'timeout',label:'Таймаут запроса / сплоита, с',min:1,max:30},{key:'clientInterval',label:'Период запуска сплоита, с',min:1,max:3600},{key:'clientWorkers',label:'Параллельных целей на клиент',min:1,max:64}]}),
 mounted(){this.load()},methods:{
 async load(){try{this.form=(await this.$http.get('/v2/farm/settings')).data;this.targets=this.form.targets.map(t=>t.name+' = '+t.host).join('\n');this.exclude=this.form.exclude.join('\n')}catch(e){this.error=e.response?.data?.error||e.message}},
 body(){return {...this.form,targets:this.targets.split('\n').filter(x=>x.trim()).map(x=>{const parts=x.split('=');if(parts.length!==2)throw Error('Цели: имя = IP');return {name:parts[0].trim(),host:parts[1].trim()}}),exclude:this.exclude.split(/[\s,]+/).filter(Boolean)}},
 async preview(){this.error='';try{this.previewTargets=(await this.$http.post('/v2/farm/targets/preview',this.body())).data}catch(e){this.error=e.response?.data?.error||e.message}},
 async save(){this.error='';this.saved=false;this.saving=true;try{this.form=(await this.$http.put('/v2/farm/settings',this.body())).data;this.saved=true}catch(e){this.error=e.response?.data?.error||e.message}finally{this.saving=false}},
 }};
</script>
